<div class="page-heading"><div><div class="eyebrow">YOUTH DIRECTORY / PROFILE</div><h1>OSY profile</h1><p>Personal details, education, and registration information.</p></div><div class="button-group"><a class="button secondary" href="<?= e(url('edit', ['id' => $person['id']])) ?>">Edit profile</a><a class="button primary" href="<?= e(url('card', ['id' => $person['id']])) ?>"><?= icon('idcards') ?> Preview ID</a></div></div>
<?php if ($person['archived_at']): ?><div class="alert">This record is archived and excluded from dashboard totals and reports.</div><?php endif; ?>
<section class="panel profile-banner"><?= avatar($person, 'large-avatar') ?><div><span class="eyebrow"><?= e($person['osy_id']) ?></span><h2><?= e($person['full_name']) ?></h2><p><?= age($person['birthdate']) ?> years old <span>·</span> <?= e($person['sex']) ?> <span>·</span> <?= e($person['employment_status']) ?></p></div><?= badge($person['status']) ?></section><div class="profile-grid">
<?php foreach (['Personal information' => ['birthdate' => 'Birthdate', 'sex' => 'Sex', 'address' => 'Address', 'contact_number' => 'Contact number'], 'Education & employment' => ['educational_attainment' => 'Educational attainment', 'last_school' => 'Last school attended', 'reason_stopped' => 'Reason for stopping school', 'employment_status' => 'Employment status'], 'Registration details' => ['osy_id' => 'OSY ID', 'date_registered' => 'Date registered', 'status' => 'Status']] as $section => $fields): ?><section class="panel form-section"><h2><?= e($section) ?></h2><dl><?php foreach ($fields as $key => $label): ?><div><dt><?= e($label) ?></dt><dd><?= e(in_array($key, ['birthdate', 'date_registered']) ? formattedDate($person[$key]) : ($person[$key] ?: 'Not provided')) ?></dd></div><?php endforeach; ?></dl></section><?php endforeach; ?>
<section class="panel form-section archive-panel"><h2><?= $person['archived_at'] ? 'Restore record' : 'Archive record' ?></h2><p><?= $person['archived_at'] ? 'Bring this youth back to the registered list and reports.' : 'Move this record out of the active directory. You can restore it anytime.' ?></p><form method="post" action="<?= e(url($person['archived_at'] ? 'restore' : 'archive', ['id' => $person['id']])) ?>" data-confirm="<?= $person['archived_at'] ? 'Restore this record?' : 'Archive this record? It will be removed from dashboard totals and reports.' ?>"><?= csrf() ?><button class="button secondary"><?= $person['archived_at'] ? 'Restore record' : 'Archive record' ?></button></form></section></div>
